    &lt;GridButtons&gt;[{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Left&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;da3c16dc-1661-41ea-9641-0510d34766a7&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;OpenAFPopup&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;b618488a-5278-436e-b42f-4586868e4c5e&quot;},&quot;ReinitForm&quot;:true,&quot;Params&quot;:null,&quot;AllowUserClose&quot;:true,&quot;CloseOnClick&quot;:true,&quot;CloseOnEscape&quot;:true},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Add.OpenForm&quot;},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Add&quot;,&quot;ModuleId&quot;:1111,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;Add&quot;,&quot;Title&quot;:&quot;New&quot;,&quot;Help&quot;:&quot;Add&quot;,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Add&quot;},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:0,&quot;CssClass&quot;:&quot;primary&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Bottom&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;06171258-45f6-49e3-a4ef-915cae345c25&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;ExcelFromEntityList&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Duplicates&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;Rename&quot;},&quot;IncludeAllFields&quot;:true,&quot;StoreAbsoluteURL&quot;:&quot;ExcelUrl&quot;,&quot;SpecialSerializationConditions&quot;:null,&quot;EntityName&quot;:null,&quot;Fields&quot;:null,&quot;RemoveFieldNames&quot;:false,&quot;UseFormulas&quot;:false,&quot;Criteria&quot;:null,&quot;Pattern&quot;:null,&quot;FilePassword&quot;:null,&quot;WorksheetPassword&quot;:null,&quot;Folder&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:null},&quot;StoreRelativeURL&quot;:null,&quot;StorePhysicalPath&quot;:null,&quot;StoreLinkClick&quot;:null,&quot;DisableForceDownload&quot;:false},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export.ExportXlsx&quot;},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;9a9e5edc-2dd2-4105-b9b1-d2eec7569175&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[ExcelUrl]&quot;,&quot;ForceDownload&quot;:true,&quot;EscapeUrl&quot;:false,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false},&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export.RedirectUrl&quot;},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=Export&quot;,&quot;ModuleId&quot;:1111,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;Export&quot;,&quot;Title&quot;:&quot;Export&quot;,&quot;Help&quot;:&quot;Export&quot;,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export&quot;},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:1,&quot;CssClass&quot;:&quot;link&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;92b42b65-9ed0-4d9c-8c1e-432e00e44729&quot;,&quot;Description&quot;:&quot;Calcul Contributii&quot;,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:0,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (\n    SELECT\n        [Initializari:ZileLucratoare_old(\n            Anul = [GetOrSession:YearV],\n            Luna = [GetOrSession:MonthV]\n        )] AS ZileLucratoare\n)\n\nSELECT\n    a.Id,\n    a.Marca,\n    a.Nume,\n\n    -------------------------------------------------\n    -- Date salarizare\n    -------------------------------------------------\n    b.Salariu                         AS SalariuBaza,\n    a.TipNorma,\n    a.ProcentLoialitate              AS ProcLoialitate,\n\n    -------------------------------------------------\n    -- Parametri lună\n    -------------------------------------------------\n    p.ZileLucratoare,\n\n    -------------------------------------------------\n    -- CO / CM\n    -------------------------------------------------\n    ISNULL(co.ZileCOLuna, 0)         AS ZileCOLuna,\n    ISNULL(cm.ZileCMLuna, 0)         AS ZileCMLuna,\n\n    -------------------------------------------------\n    -- Zile lucrate efectiv\n    -------------------------------------------------\n    zl.ZileLucrate,\n\n    -------------------------------------------------\n    -- Ore lucrate\n    -------------------------------------------------\n    bc.OreLucrate,\n\n    -------------------------------------------------\n    -- Salariu brut efectiv lucrat\n    -------------------------------------------------\n    bc.SalBrutEfectiv,\n\n    -------------------------------------------------\n    -- Spor loialitate pentru zile lucrate\n    -------------------------------------------------\n    bc.LoialitateSalEf,\n\n    -------------------------------------------------\n    -- Salariu CO\n    -------------------------------------------------\n    bc.SalCO,\n\n    -------------------------------------------------\n    -- Spor loialitate CO\n    -------------------------------------------------\n    bc.LoialitateCO,\n\n    -------------------------------------------------\n    -- Total CO\n    -------------------------------------------------\n    bc.TotalCO,\n\n    -------------------------------------------------\n    -- Tichete\n    -------------------------------------------------\n    bc.TicheteTotale,\n\n    -------------------------------------------------\n    -- TOTAL BRUT\n    -------------------------------------------------\n    bc.TotalBrut\n\nFROM app.Salariat a\n\nLEFT JOIN app.NomGrilaSalarizare b\n       ON b.Clasa = a.Clasa\n      AND b.TipMediu = &#39;U&#39;\n\nLEFT JOIN app.TSTichetMasa t\n       ON t.Anul = a.Anul\n      AND t.Luna = a.Luna\n\nCROSS JOIN Parametri p\n\n-----------------------------------------------------------\n-- Zile Concediu de Odihnă\n-----------------------------------------------------------\nOUTER APPLY (\n    SELECT\n        SUM(\n            CASE\n                WHEN MONTH(c.Interval1DatadeInceput) = @Luna\n                 AND YEAR(c.Interval1DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO1, 0)\n                ELSE 0\n            END\n          +\n            CASE\n                WHEN MONTH(c.Interval2DatadeInceput) = @Luna\n                 AND YEAR(c.Interval2DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO2, 0)\n                ELSE 0\n            END\n          +\n            CASE\n                WHEN MONTH(c.Interval3DatadeInceput) = @Luna\n                 AND YEAR(c.Interval3DatadeInceput) = @Anul\n                THEN ISNULL(c.NrZileCO3, 0)\n                ELSE 0\n            END\n        ) AS ZileCOLuna\n    FROM app.ConcediudeOdihna c\n    WHERE c.Marca = a.Marca\n      AND c.CodSucursala = @CodSucursala\n) co\n\n-----------------------------------------------------------\n-- Zile Concediu Medical\n-----------------------------------------------------------\nOUTER APPLY (\n    SELECT\n        SUM(m.TotZileLucratoare) AS ZileCMLuna\n    FROM app.ConcediuMedical m\n    WHERE m.Marca = a.Marca\n      AND m.CodSucursala = @CodSucursala\n      AND m.AnulDePlata = @Anul\n      AND m.LunaDePlata = @Luna\n) cm\n\n-----------------------------------------------------------\n-- Zile lucrate efectiv\n-----------------------------------------------------------\nCROSS APPLY (\n    SELECT\n        CASE\n            WHEN p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna, 0)\n                 - ISNULL(cm.ZileCMLuna, 0) &amp;lt; 0\n            THEN 0\n            ELSE p.ZileLucratoare\n                 - ISNULL(co.ZileCOLuna, 0)\n                 - ISNULL(cm.ZileCMLuna, 0)\n        END AS ZileLucrate\n) zl\n\n-----------------------------------------------------------\n-- Baza calcul TOTAL BRUT\n-----------------------------------------------------------\nCROSS APPLY (\n    SELECT\n\n        -----------------------------------------\n        -- Ore lucrate\n        -----------------------------------------\n        zl.ZileLucrate * a.TipNorma * 8\n            AS OreLucrate,\n\n        -----------------------------------------\n        -- Salariu brut efectiv lucrat\n        -----------------------------------------\n        ROUND(\n            b.Salariu\n            / p.ZileLucratoare\n            * zl.ZileLucrate\n            * a.TipNorma,\n            0\n        ) AS SalBrutEfectiv,\n\n        -----------------------------------------\n        -- Loialitate salariu efectiv\n        -----------------------------------------\n        ROUND(\n            ROUND(\n                b.Salariu\n                / p.ZileLucratoare\n                * zl.ZileLucrate\n                * a.TipNorma,\n                0\n            ) * a.ProcentLoialitate,\n            0\n        ) AS LoialitateSalEf,\n\n        -----------------------------------------\n        -- Salariu CO\n        -----------------------------------------\n        ROUND(\n            b.Salariu\n            / p.ZileLucratoare\n            * ISNULL(co.ZileCOLuna,0)\n            * a.TipNorma,\n            0\n        ) AS SalCO,\n\n        -----------------------------------------\n        -- Loialitate CO\n        -----------------------------------------\n        ROUND(\n            ROUND(\n                b.Salariu\n                / p.ZileLucratoare\n                * ISNULL(co.ZileCOLuna,0)\n                * a.TipNorma,\n                0\n            ) * a.ProcentLoialitate,\n            0\n        ) AS LoialitateCO,\n\n        -----------------------------------------\n        -- Total CO\n        -----------------------------------------\n        ROUND(\n            b.Salariu\n            / p.ZileLucratoare\n            * ISNULL(co.ZileCOLuna,0)\n            * a.TipNorma,\n            0\n        )\n        +\n        ROUND(\n            ROUND(\n                b.Salariu\n                / p.ZileLucratoare\n                * ISNULL(co.ZileCOLuna,0)\n                * a.TipNorma,\n                0\n            ) * a.ProcentLoialitate,\n            0\n        ) AS TotalCO,\n\n        -----------------------------------------\n        -- Tichete\n        -----------------------------------------\n        ISNULL(t.Valoare,0)\n        * zl.ZileLucrate\n            AS TicheteTotale,\n\n        -----------------------------------------\n        -- TOTAL BRUT\n        -----------------------------------------\n        (\n            -------------------------------------\n            -- Salariu lucrat\n            -------------------------------------\n            ROUND(\n                b.Salariu\n                / p.ZileLucratoare\n                * zl.ZileLucrate\n                * a.TipNorma,\n                0\n            )\n\n            -------------------------------------\n            -- Loialitate lucrat\n            -------------------------------------\n            +\n            ROUND(\n                ROUND(\n                    b.Salariu\n                    / p.ZileLucratoare\n                    * zl.ZileLucrate\n                    * a.TipNorma,\n                    0\n                ) * a.ProcentLoialitate,\n                0\n            )\n\n            -------------------------------------\n            -- Salariu CO\n            -------------------------------------\n            +\n            ROUND(\n                b.Salariu\n                / p.ZileLucratoare\n                * ISNULL(co.ZileCOLuna,0)\n                * a.TipNorma,\n                0\n            )\n\n            -------------------------------------\n            -- Loialitate CO\n            -------------------------------------\n            +\n            ROUND(\n                ROUND(\n                    b.Salariu\n                    / p.ZileLucratoare\n                    * ISNULL(co.ZileCOLuna,0)\n                    * a.TipNorma,\n                    0\n                ) * a.ProcentLoialitate,\n                0\n            )\n\n            -------------------------------------\n            -- Tichete\n            -------------------------------------\n            +\n            (\n                ISNULL(t.Valoare,0)\n                * zl.ZileLucrate\n            )\n\n        ) AS TotalBrut\n\n) bc\n\nWHERE a.Anul = @Anul\n  AND a.Luna = @Luna\n  AND a.CodSucursala = @CodSucursala\n\nORDER BY a.Nume;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}},{&quot;Id&quot;:-1,&quot;IsDeleted&quot;:false,&quot;ActionInfo&quot;:{&quot;Id&quot;:-1,&quot;GlobalId&quot;:&quot;2a28449d-5582-4a4c-b928-e1cc91bc165b&quot;,&quot;Description&quot;:null,&quot;ActionErrorMessage&quot;:null,&quot;ActionStackId&quot;:-1,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;Condition&quot;:null,&quot;IsDeleted&quot;:false,&quot;IsDisabled&quot;:false,&quot;OrderIndex&quot;:1,&quot;DiagramUID&quot;:null,&quot;ActionParameters&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;3e7b8ebc-7c9a-47ce-8c04-f3738fee6221&quot;}},&quot;Metadata&quot;:{},&quot;HasActionParameters&quot;:true}}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;OnItemClickActionStackId&quot;:-1,&quot;OnBulkClickActionStackId&quot;:-1,&quot;OnBulkClickAfterActionStackId&quot;:-1,&quot;Url&quot;:&quot;&amp;amp;buttonName=CalculContributii&quot;,&quot;ModuleId&quot;:1111,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;CalculContributii&quot;,&quot;Title&quot;:&quot;Calcul Contributii&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:2,&quot;CssClass&quot;:&quot;primary&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false}]&lt;/GridButtons&gt;
